function Navbar(){

return(

<div className="navbar">

<h2>CareerHub</h2>

<div>

<Link to="/">Home</Link>

<Link to="/internships">Internships</Link>

<Link to="/jobs">Jobs</Link>

</div>

</div>

)

}

export default Navbar;
